#include <iostream>
#include <memory>
#include <vector>
#include <string>

// Abstract Base Class
class Shape {
public:
    virtual ~Shape() = default; // Essential virtual destructor for polymorphic base

    // Pure virtual function enforcing polymorphic interface
    virtual double area() const = 0;

    // Regular virtual function with default implementation
    virtual std::string getName() const {
        return "Generic Shape";
    }
};

// Concrete Derived Class Circle
class Circle : public Shape {
private:
    double radius;
public:
    explicit Circle(double r) : radius(r) {}

    double area() const override {
        return 3.141592653589793 * radius * radius;
    }

    std::string getName() const override {
        return "Circle";
    }
};

// Concrete Derived Class Rectangle
class Rectangle : public Shape {
private:
    double width;
    double height;
public:
    Rectangle(double w, double h) : width(w), height(h) {}

    double area() const override {
        return width * height;
    }

    std::string getName() const override {
        return "Rectangle";
    }
};

int main() {
    // Vector of smart pointers to abstract base class Shape
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(3.0));
    shapes.push_back(std::make_unique<Rectangle>(4.0, 5.0));

    for (const auto& shapePtr : shapes) {
        std::cout << shapePtr->getName() << " area: " << shapePtr->area() << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <iomanip>

// Abstract Base Class Employee
class Employee {
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)) {}

    virtual ~Employee() = default; // Essential virtual destructor

    const std::string& getFirstName() const { return firstName; }
    const std::string& getLastName() const { return lastName; }
    const std::string& getSSN() const { return socialSecurityNumber; }

    // Pure virtual function enforcing interface inheritance
    virtual double earnings() const = 0;

    virtual void print() const {
        std::cout << firstName << " " << lastName << "\nSSN: " << socialSecurityNumber;
    }
};

// Concrete Derived Class: SalariedEmployee
class SalariedEmployee : public Employee {
private:
    double weeklySalary;
public:
    SalariedEmployee(std::string first, std::string last, std::string ssn, double salary)
        : Employee(std::move(first), std::move(last), std::move(ssn)), weeklySalary(salary) {}

    double earnings() const override {
        return weeklySalary;
    }

    void print() const override {
        std::cout << "salaried employee: ";
        Employee::print();
        std::cout << "\nweekly salary: $" << weeklySalary;
    }
};

// Concrete Derived Class: CommissionEmployee
class CommissionEmployee : public Employee {
protected:
    double grossSales;
    double commissionRate;
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn, double sales, double rate)
        : Employee(std::move(first), std::move(last), std::move(ssn)), grossSales(sales), commissionRate(rate) {}

    double earnings() const override {
        return commissionRate * grossSales;
    }

    void print() const override {
        std::cout << "commission employee: ";
        Employee::print();
        std::cout << "\ngross sales: $" << grossSales 
                  << "; commission rate: " << commissionRate;
    }
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    std::vector<std::unique_ptr<Employee>> staff;
    staff.push_back(std::make_unique<SalariedEmployee>("John", "Smith", "111-11-1111", 800.00));
    staff.push_back(std::make_unique<CommissionEmployee>("Sue", "Jones", "222-22-2222", 10000.00, 0.06));

    for (const auto& emp : staff) {
        emp->print();
        std::cout << "\nearnings: $" << emp->earnings() << "\n---\n";
    }

    return 0;
}
